import{_ as s,o as i,c as a,a2 as n}from"./chunks/framework.CvydjLy7.js";const k=JSON.parse('{"title":"一、外部化配置：搞清楚谁覆盖谁","description":"","frontmatter":{"title":"一、外部化配置：搞清楚谁覆盖谁"},"headers":[{"level":3,"title":"1.1 官方定义的配置源优先级","slug":"_1-1-官方定义的配置源优先级","link":"#_1-1-官方定义的配置源优先级","children":[]},{"level":3,"title":"1.2 application.yml 内部的四层顺序","slug":"_1-2-application-yml-内部的四层顺序","link":"#_1-2-application-yml-内部的四层顺序","children":[]},{"level":3,"title":"1.3 占位符、随机值与引用","slug":"_1-3-占位符、随机值与引用","link":"#_1-3-占位符、随机值与引用","children":[]},{"level":3,"title":"1.4 spring.config.import：拆分与引入","slug":"_1-4-spring-config-import-拆分与引入","link":"#_1-4-spring-config-import-拆分与引入","children":[]}],"relativePath":"ch03/01.md","filePath":"ch03/01.md","lastUpdated":1789497795000}'),e={name:"ch03/01.md"};function l(d,t,o,p,r,c){return i(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="一、外部化配置-搞清楚谁覆盖谁" tabindex="-1">一、外部化配置：搞清楚谁覆盖谁 <a class="header-anchor" href="#一、外部化配置-搞清楚谁覆盖谁" aria-label="Permalink to &quot;一、外部化配置：搞清楚谁覆盖谁&quot;">​</a></h1><h3 id="_1-1-官方定义的配置源优先级" tabindex="-1">1.1 官方定义的配置源优先级 <a class="header-anchor" href="#_1-1-官方定义的配置源优先级" aria-label="Permalink to &quot;1.1 官方定义的配置源优先级&quot;">​</a></h3><p>官方文档给出了完整的 PropertySource 顺序，<strong>序号越小优先级越高</strong>（即 15 最高，1 最低）。以下是原文列表：</p><table tabindex="0"><thead><tr><th>优先级</th><th>来源</th><th>说明</th></tr></thead><tbody><tr><td>15</td><td>DevTools 全局设置</td><td><code>$HOME/.config/spring-boot</code> 目录下，仅 DevTools 激活时生效</td></tr><tr><td>14</td><td><code>@TestPropertySource</code></td><td>测试类上的注解</td></tr><tr><td>13</td><td><code>@DynamicPropertySource</code></td><td>测试中动态注册属性（Testcontainers 常用）</td></tr><tr><td>12</td><td>测试注解的 <code>properties</code> 属性</td><td>如 <code>@SpringBootTest(properties = ...)</code></td></tr><tr><td><strong>11</strong></td><td><strong>命令行参数</strong></td><td><code>java -jar app.jar --server.port=9090</code></td></tr><tr><td>10</td><td><code>SPRING_APPLICATION_JSON</code></td><td>环境变量或系统属性里的内联 JSON</td></tr><tr><td>9</td><td><code>ServletConfig</code> 初始化参数</td><td>——</td></tr><tr><td>8</td><td><code>ServletContext</code> 初始化参数</td><td>——</td></tr><tr><td>7</td><td>JNDI 属性（<code>java:comp/env</code>）</td><td>传统应用服务器场景</td></tr><tr><td>6</td><td>Java 系统属性</td><td><code>System.getProperties()</code>，即 <code>-D</code> 参数</td></tr><tr><td><strong>5</strong></td><td><strong>操作系统环境变量</strong></td><td>容器部署时的主要配置方式</td></tr><tr><td>4</td><td><code>RandomValuePropertySource</code></td><td>只提供 <code>random.*</code> 属性</td></tr><tr><td><strong>3</strong></td><td><strong>Config data</strong>（<code>application.yml</code> 等）</td><td>日常开发最常用的一层</td></tr><tr><td>2</td><td><code>@PropertySource</code></td><td>注意：这类属性源直到容器刷新时才加入 Environment</td></tr><tr><td>1</td><td>默认属性</td><td><code>SpringApplication.setDefaultProperties(Map)</code></td></tr></tbody></table><blockquote><p><strong>两个必须记住的结论</strong></p><p>**一、命令行参数优先级高于配置文件。**所以 <code>java -jar app.jar --server.port=9090</code> 一定覆盖 <code>application.yml</code> 里的 <code>server.port</code>。上线排查问题时，先用这个手段临时改配置，不用改包。</p><p>**二、环境变量优先级也高于配置文件。**容器里常通过 <code>SPRING_DATASOURCE_URL</code> 这类变量注入配置。如果你改了 yml 却不生效，先检查环境变量里有没有同名的项。</p></blockquote><h3 id="_1-2-application-yml-内部的四层顺序" tabindex="-1">1.2 application.yml 内部的四层顺序 <a class="header-anchor" href="#_1-2-application-yml-内部的四层顺序" aria-label="Permalink to &quot;1.2 application.yml 内部的四层顺序&quot;">​</a></h3><p>第 3 层的 “Config data” 内部还有细分，从高到低是：</p><ol><li><strong>jar 包外、带 Profile 的文件</strong> <code>./config/application-dev.yml</code> → <code>./application-dev.yml</code></li><li><strong>jar 包外、不带 Profile 的文件</strong> <code>./config/application.yml</code> → <code>./application.yml</code></li><li><strong>jar 包内、带 Profile 的文件</strong> <code>classpath:/application-dev.yml</code></li><li><strong>jar 包内、不带 Profile 的文件</strong> <code>classpath:/application.yml</code></li></ol><blockquote><p><strong>这个顺序的实际用法</strong></p><p>正因为<strong>包外文件优先级高于包内</strong>，部署时可以在 jar 旁边放一个 <code>config/application-prod.yml</code> 覆盖打包进去的配置 —— 数据库密码这类敏感信息就不必打进制品。这也是官方推荐的“同一份制品部署到多个环境”的做法。</p></blockquote><h3 id="_1-3-占位符、随机值与引用" tabindex="-1">1.3 占位符、随机值与引用 <a class="header-anchor" href="#_1-3-占位符、随机值与引用" aria-label="Permalink to &quot;1.3 占位符、随机值与引用&quot;">​</a></h3><p><code>application.yml</code></p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 引用其他配置项</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">activity-server</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${app.name} —— 教学用校园活动服务平台</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 带默认值的引用：找不到就用冒号后面的值</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  upload-dir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${UPLOAD_DIR:./storage}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 环境变量优先，缺失时回落</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  db-url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${DATABASE_URL:jdbc:h2:mem:activity}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 随机值：只在启动时生成一次</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  instance-id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${random.uuid}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  instance-port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${random.int(10000,20000)}</span></span></code></pre></div><p>随机值在<strong>需要多个实例互不冲突的场景</strong>（如节点标识、测试端口）很实用。注意它的作用域：同一个属性名在同一个应用里只会生成一次。</p><h3 id="_1-4-spring-config-import-拆分与引入" tabindex="-1">1.4 spring.config.import：拆分与引入 <a class="header-anchor" href="#_1-4-spring-config-import-拆分与引入" aria-label="Permalink to &quot;1.4 spring.config.import：拆分与引入&quot;">​</a></h3><p>配置项变多之后，把配置按用途拆成多个文件更易维护：</p><p><code>application.yml</code></p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">classpath:config/datasource.yml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">classpath:config/cache.yml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">optional:file:./local-overrides.yml</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # optional: 前缀表示文件不存在也不报错</span></span></code></pre></div><blockquote><p><strong>被导入的文件优先级更高</strong></p><p><code>spring.config.import</code> 导入的配置<strong>优先级高于导入它的那个文件</strong>，这点与直觉相反，配置没生效时要留意。另外 <code>optional:</code> 前缀很重要 —— 不加的话，文件缺失会直接导致启动失败。</p></blockquote>`,18)])])}const g=s(e,[["render",l]]);export{k as __pageData,g as default};
